//! The pages' inline scripts, exactly as v1 `grid/pages.js` wrote them (the CSP allows inline script on grid pages).

/// Every form and sign-in link: the button spins at once while the next page loads, and a second press does nothing. Back from the browser cache clears it. Script that sends a form itself cancels the submit first: then it's not pending here.
pub(super) const PENDING: &str = r#"<script>(()=>{const go=(b)=>{if(b)setTimeout(()=>{b.classList.add('wait');b.setAttribute('aria-busy','true')})};document.addEventListener('submit',(e)=>{if(e.defaultPrevented)return;const b=e.submitter||e.target.querySelector('button');if(b&&b.classList.contains('wait'))return e.preventDefault();go(b)});document.addEventListener('click',(e)=>{const a=e.target.closest('a[href^="/auth/"]');if(a)go(a)});addEventListener('pageshow',()=>document.querySelectorAll('.wait').forEach((b)=>{b.classList.remove('wait');b.removeAttribute('aria-busy')}))})()</script>"#;

